module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] cycle_count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            cycle_count <= 4'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                if (ped) begin
                    next_state <= 3'd0;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd0;
                    cycle_count <= 4'd0;
                end
            end else if (state == 3'd1) begin
                if (ped) begin
                    next_state <= 3'd2;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd1;
                    cycle_count <= 4'd0;
                end
            end else if (state == 3'd2) begin
                if (ped) begin
                    next_state <= 3'd2;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd1;
                    cycle_count <= 4'd0;
                end
            end else if (state == 3'd3) begin
                if (ped) begin
                    next_state <= 3'd2;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd3;
                    cycle_count <= 4'd0;
                end
            end else if (state == 3'd4) begin
                if (ped) begin
                    next_state <= 3'd2;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd4;
                    cycle_count <= 4'd0;
                end
            end else if (state == 3'd5) begin
                if (ped) begin
                    next_state <= 3'd2;
                    cycle_count <= 4'd0;
                end else begin
                    next_state <= 3'd5;
                    cycle_count <= 4'd0;
                end
            end
            state <= next_state;
            cycle_count <= cycle_count + 1;
            if (cycle_count == 4'd3) begin
                if (state == 3'd0) begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end else if (state == 3'd1) begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end else if (state == 3'd2) begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end else if (state == 3'd3) begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end else if (state == 3'd4) begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end else if (state == 3'd5) begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
            end
        end
    end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [1:0] next_light;
reg [3:0] counter;

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
        counter <= 4'd0;
    end else begin
        if (light == 2'b00) begin // RED
            if (counter == 3'd2) begin
                next_light <= 2'b01; // GREEN
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (light == 2'b01) begin // GREEN
            if (counter == 3'd3) begin
                next_light <= 2'b10; // YELLOW
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (light == 2'b10) begin // YELLOW
            if (counter == 3'd1) begin
                next_light <= 2'b00; // RED
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (light == 2'b01 && ped) begin // GREEN and ped pressed
            next_light <= 2'b10;
            counter <= 4'd0;
        end else begin
            light <= next_light;
            walk <= (light == 2'b00) ? 1'b1 : 1'b0;
        end
    end
end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [2:0] state;
reg [2:0] next_state;
reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        count <= 4'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            if (count == 3'd3) begin
                next_state <= 3'd1;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end else if (state == 3'd1) begin
            if (count == 4'd4) begin
                next_state <= 3'd2;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end else if (state == 3'd2) begin
            if (count == 2'd2) begin
                next_state <= 3'd0;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        count <= 4'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else if (state == 3'd1) begin
            light <= 2'b01;
            walk <= 1'b0;
        end else if (state == 3'd2) begin
            light <= 2'b10;
            walk <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        count <= 4'd0;
    end else begin
        if (state == 3'd1 && ped) begin
            next_state <= 3'd2;
            count <= 4'd0;
        end else begin
            state <= next_state;
        end
    end
end

endmodule

