    end else begin
        if (state == 3'd0) begin
            next_state <= 3'd0;
            counter <= 4'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else if (state == 3'd1) begin
            if (counter == 3'd3) begin
                next_state <= 3'd2;
                counter <= 4'd0;
            end else begin
                next_state <= 3'd1;
                counter <= counter + 1;
            end
        end else if (state == 3'd2) begin
            if (counter == 3'd4) begin
                next_state <= 3'd3;
                counter <= 4'd0;
            end else begin
                next_state <= 3'd2;
                counter <= counter + 1;
            end
        end else if (state == 3'd3) begin
            if (counter == 3'd2) begin
                next_state <= 3'd0;
                counter <= 4'd0;
            end else begin
                next_state <= 3'd3;
                counter <= counter + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        counter <= 4'd0;
    end else begin
        state <= next_state;
    end
end

always @(posedge clk) begin
    if (reset) begin
        counter <= 4'd0;
    end else begin
        if (state == 3'd0) begin
            counter <= 4'd0;
        end else if (state == 3'd1) begin
            if (counter < 3'd3) begin
                counter <= counter + 1;
            end
        end else if (state == 3'd2) begin
            if (counter < 3'd4) begin
                counter <= counter + 1;
            end
        end else if (state == 3'd3) begin
            if (counter < 3'd2) begin
                counter <= counter + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else if (state == 3'd1) begin
            light <= 2'b01;
            walk <= 1'b0;
        end else if (state == 3'd2) begin
            light <= 2'b10;
            walk <= 1'b0;
        end else if (state == 3'd3) begin
            light <= 2'b00;
            walk <= 1'b1;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            walk <= 1'b1;
        end else begin
            walk <= 1'b0;
        end
    end
end

